         */

        /*
         * Now get last part - the description
         */
        EATAB;
        if (l[0] == '\b') {
                ++l;
                m->flag |= NOSPACE;
        } else if ((l[0] == '\\') && (l[1] == 'b')) {
                ++l;
                ++l;
                m->flag |= NOSPACE;
        }
        for (i = 0; (m->desc[i++] = *l++) != '\0' && i < sizeof(m->desc); )

getvalue(struct magic_set *ms, struct magic *m, const char **p, int action)
{
        char *ep;
        uint64_t ull;

        switch (m->type) {
        case FILE_BESTRING16:
        case FILE_LESTRING16:
        case FILE_STRING:
        case FILE_PSTRING:
        case FILE_REGEX:
        case FILE_SEARCH:
        case FILE_NAME:
        case FILE_USE:
        case FILE_DER:
        case FILE_OCTAL:
                *p = getstr(ms, m, *p, action == FILE_COMPILE);
                if (*p == NULL) {
                        if (ms->flags & MAGIC_CHECK)
                                file_magwarn(ms, "cannot get string from `%s'",
                                    m->value.s);
                        return -1;
                }
                if (m->type == FILE_REGEX) {
                        file_regex_t rx;
                        int rc = file_regcomp(ms, &rx, m->value.s,
                            REG_EXTENDED);
                        if (rc == 0) {
                                file_regfree(&rx);
                        }
                        return rc ? -1 : 0;
                }
                return 0;
        default:
                if (m->reln == 'x')
                        return 0;
                break;
        }

        switch (m->type) {
        case FILE_FLOAT:
        case FILE_BEFLOAT:
        case FILE_LEFLOAT:
                errno = 0;
#ifdef HAVE_STRTOF
                m->value.f = strtof(*p, &ep);
#else
                m->value.f = (float)strtod(*p, &ep);
#endif
                if (errno == 0)
                        *p = ep;
                return 0;
        case FILE_DOUBLE:
        case FILE_BEDOUBLE:
        case FILE_LEDOUBLE:
                errno = 0;
                m->value.d = strtod(*p, &ep);
                if (errno == 0)
                        *p = ep;
                return 0;
        case FILE_GUID:
                if (file_parse_guid(*p, m->value.guid) == -1)
                        return -1;
                *p += FILE_GUID_SIZE - 1;
                return 0;
        default:
                errno = 0;
                ull = CAST(uint64_t, strtoull(*p, &ep, 0));
                m->value.q = file_signextend(ms, m, ull);
                if (*p == ep) {
                        file_magwarn(ms, "Unparsable number `%s'", *p);
                } else {
                        size_t ts = typesize(m->type);
                        uint64_t x;
                        const char *q;

                        if (ts == FILE_BADSIZE) {
                                file_magwarn(ms,
                                    "Expected numeric type got `%s'",
                                    type_tbl[m->type].name);
                        }
                        for (q = *p; isspace(CAST(unsigned char, *q)); q++)
                                continue;
                        if (*q == '-')
                                ull = -CAST(int64_t, ull);
                        switch (ts) {
                        case 1:
                                x = CAST(uint64_t, ull & ~0xffULL);
                                break;
                        case 2:
                                x = CAST(uint64_t, ull & ~0xffffULL);
                                break;
                        case 4:
                                x = CAST(uint64_t, ull & ~0xffffffffULL);
                                break;
                        case 8:
                                x = 0;
                                break;
                        default:
                                fprintf(stderr, "Bad width %zu", ts);
                                abort();
                        }
                        if (x) {
                                file_magwarn(ms, "Overflow for numeric"
                                    " type `%s' value %#" PRIx64,
                                    type_tbl[m->type].name, ull);
                        }
                }
                if (errno == 0) {
                        *p = ep;
                        eatsize(p);
                }
                return 0;
        }
}

/*
 * Convert a string containing C character escapes.  Stop at an unescaped
 * space or tab.
 * Copy the converted version to "m->value.s", and the length in m->vallen.
 * Return updated scan pointer as function result. Warn if set.
 */
private const char *
getstr(struct magic_set *ms, struct magic *m, const char *s, int warn)
{
        const char *origs = s;
        char    *p = m->value.s;
        size_t  plen = sizeof(m->value.s);
        char    *origp = p;
        char    *pmax = p + plen - 1;
        int     c;
        int     val;
        size_t  bracket_nesting = 0;

        while ((c = *s++) != '\0') {
                if (isspace(CAST(unsigned char, c)))
                        break;
                if (p >= pmax) {
                        file_error(ms, 0, "string too long: `%s'", origs);
                        return NULL;
                }
                if (c != '\\') {
                    if (c == '[') {
                            bracket_nesting++;
                    }
                    if (c == ']' && bracket_nesting > 0) {
                            bracket_nesting--;
                    }
                    *p++ = CAST(char, c);
                    continue;
                }
                switch(c = *s++) {

                case '\0':
                        if (warn)
                                file_magwarn(ms, "incomplete escape");
                        s--;
                        goto out;
                case '.':
                        if (m->type == FILE_REGEX &&
                            bracket_nesting == 0 && warn) {
                                file_magwarn(ms, "escaped dot ('.') found, "
                                    "use \\\\. instead");
                        }
                        warn = 0; /* already did */
                        /*FALLTHROUGH*/
                case '\t':
                        if (warn) {
                                file_magwarn(ms,
                                    "escaped tab found, use \\\\t instead");
                                warn = 0;       /* already did */
                        }
                        /*FALLTHROUGH*/
                default:
                        if (warn) {
                                if (isprint(CAST(unsigned char, c))) {
                                        /* Allow escaping of
                                         * ``relations'' */
                                        if (strchr("<>&^=!", c) == NULL
                                            && (m->type != FILE_REGEX ||
                                            strchr("[]().*?^$|{}", c)
                                            == NULL)) {
                                                file_magwarn(ms, "no "
                                                    "need to escape "
                                                    "`%c'", c);
                                        }
                                } else {
                                        file_magwarn(ms,
