/* Single hex char to int; -1 if not a hex char. */
private int
hextoint(int c)
{
        if (!isascii(CAST(unsigned char, c)))
                return -1;
        if (isdigit(CAST(unsigned char, c)))
                return c - '0';
        if ((c >= 'a') && (c <= 'f'))
                return c + 10 - 'a';
        if (( c>= 'A') && (c <= 'F'))
                return c + 10 - 'A';
        return -1;
}


/*
 * Print a string containing C character escapes.
 */
protected void
file_showstr(FILE *fp, const char *s, size_t len)
{
        char    c;

        for (;;) {
                if (len == FILE_BADSIZE) {
                        c = *s++;
                        if (c == '\0')
                                break;
                }
                else  {
                        if (len-- == 0)
                                break;
                        c = *s++;
                }
                if (c >= 040 && c <= 0176)      /* TODO isprint && !iscntrl */
                        (void) fputc(c, fp);
                else {
                        (void) fputc('\\', fp);
                        switch (c) {
                        case '\a':
                                (void) fputc('a', fp);
                                break;

                        case '\b':
                                (void) fputc('b', fp);
                                break;

                        case '\f':
                                (void) fputc('f', fp);
                                break;

                        case '\n':
                                (void) fputc('n', fp);
                                break;

                        case '\r':
                                (void) fputc('r', fp);
                                break;

                        case '\t':
                                (void) fputc('t', fp);
                                break;

                        case '\v':
                                (void) fputc('v', fp);
                                break;

                        default:
                                (void) fprintf(fp, "%.3o", c & 0377);
                                break;
                        }
                }
        }
}

/*
 * eatsize(): Eat the size spec from a number [eg. 10UL]
 */
private void
eatsize(const char **p)
{
        const char *l = *p;

        if (LOWCASE(*l) == 'u')
                l++;

        switch (LOWCASE(*l)) {
        case 'l':    /* long */
        case 's':    /* short */
        case 'h':    /* short */
        case 'b':    /* char/byte */
        case 'c':    /* char/byte */
                l++;
                /*FALLTHROUGH*/
        default:
                break;
        }

        *p = l;
}

/*
